const TZ = 'America/Sao_Paulo';
let teste = false;
try { teste = $('Testar (manual)').isExecuted; } catch (e) { teste = false; }
const a = DateTime.now().setZone(TZ);
const h = a.hour;
const momento = h < 9 ? 'manha' : h < 11 ? 'checkin' : h < 13 ? 'meio_dia' : h < 16 ? 'checkin' : h < 20 ? 'tarde' : 'noite';
return [{ json: { momento, teste } }];

const TZ = 'America/Sao_Paulo';
const GRUPO = '120363412854461070@g.us';
const FAMILIA = ['Daniel', 'Quézia', 'Eliezer'];
const NL = String.fromCharCode(10);
const M = $('Momento').first().json;
const agora = DateTime.now().setZone(TZ).setLocale('pt-BR');
const ini = agora.startOf('day'), fim = agora.endOf('day');
const rows = n => { try { return $(n).all().map(i => i.json).filter(r => r && r.id != null); } catch (e) { return []; } };
const dt = v => { if (!v) return null; let d = DateTime.fromISO(String(v)); if (!d.isValid) d = DateTime.fromSQL(String(v)); return d.isValid ? d.setZone(TZ) : null; };
const ehHoje = d => !!d && d >= ini && d <= fim;
const brl = v => { const [i, c] = Math.abs(Number(v) || 0).toFixed(2).split('.'); return 'R$ ' + i.replace(/\B(?=(\d{3})+(?!\d))/g, '.') + ',' + c; };
const de = r => r.autor || 'Daniel';
let dest = {};
try { dest = $('Supabase: clientes atendidos').first().json || {}; } catch (e) { dest = {}; }
const LEMB = rows('Lembretes');
const TAR = rows('Tarefas');
const TRA = rows('Transações de hoje');
const CON = rows('Contas');
const MSG = rows('Mensagens recentes');

function dados(a) {
  const L = LEMB.filter(r => de(r) === a).map(r => ({ ...r, d: dt(r.quando) }));
  const proximos = L.filter(r => r.status === 'pendente' && ehHoje(r.d) && r.d > agora).sort((x, y) => x.d - y.d);
  const semOk = L.filter(r => r.status === 'aguardando');
  const feitos = L.filter(r => r.status === 'concluido' && ehHoje(dt(r.updatedAt)));
  const contas = CON.filter(r => de(r) === a && !['paga', 'pago', 'cancelada', 'cancelado'].includes(String(r.status || '').toLowerCase()) && ehHoje(dt(r.vencimento)));
  const abertas = TAR.filter(r => de(r) === a && r.status === 'aberta');
  const urgentes = abertas.filter(r => { const p = dt(r.prazo); return p && p <= fim; });
  const feitasHoje = TAR.filter(r => de(r) === a && r.status === 'concluida' && ehHoje(dt(r.updatedAt)));
  const tr = TRA.filter(r => de(r) === a && ehHoje(dt(r.data)));
  const gastos = tr.filter(r => String(r.tipo || 'despesa') !== 'receita');
  const receitas = tr.filter(r => String(r.tipo) === 'receita');
  const ativo2h = MSG.some(r => r.papel === 'usuario' && de(r) === a && dt(r.createdAt) && dt(r.createdAt) >= agora.minus({ hours: 2 }));
  return { proximos, semOk, feitos, contas, abertas, urgentes, feitasHoje, gastos, receitas, ativo2h };
}
const linhaL = r => '• ' + r.d.toFormat('HH:mm') + ' — ' + String(r.texto || '').split(NL)[0].slice(0, 90);
function blocoAgenda(x) {
  const b = [];
  if (x.proximos.length) b.push('⏰ *Lembretes ainda hoje:*' + NL + x.proximos.slice(0, 8).map(linhaL).join(NL));
  if (x.semOk.length) b.push('🔔 *Esperando seu ok:*' + NL + x.semOk.slice(0, 5).map(r => '• ' + String(r.texto || '').split(NL)[0].slice(0, 90)).join(NL));
  if (x.contas.length) b.push('💸 *Vence hoje:*' + NL + x.contas.slice(0, 5).map(r => '• ' + (r.descricao || r.beneficiario || 'conta') + (r.valor ? ' — ' + brl(r.valor) : '')).join(NL));
  return b;
}
function textoCliente(a, mom) {
  const n = String(a).split(' ')[0];
  const x = dados(a);
  if (mom === 'manha') {
    const b = blocoAgenda(x);
    if (x.urgentes.length) b.push('📋 *Tarefas para hoje ou atrasadas:*' + NL + x.urgentes.slice(0, 5).map(t => '• ' + t.titulo).join(NL));
    else if (x.abertas.length) b.push('📋 ' + x.abertas.length + (x.abertas.length === 1 ? ' tarefa aberta' : ' tarefas abertas'));
    return '☀️ *Bom dia, ' + n + '!* ' + (b.length ? 'Seu dia hoje:' + NL + NL + b.join(NL + NL) : 'Nada agendado pra hoje 🙌') + NL + NL + 'Gastou algo? É só me mandar por texto, áudio ou foto do comprovante.';
  }
  if (mom === 'meio_dia') {
    const b = blocoAgenda(x);
    if (!b.length) return null;
    return '🕛 *' + n + ', resumo do meio-dia*' + NL + NL + b.join(NL + NL);
  }
  if (mom === 'tarde') {
    const b = blocoAgenda(x);
    const pergunta = x.ativo2h ? '' : 'E aí, teve algum gasto à tarde que ainda não me contou? 😉';
    if (!b.length && !pergunta) return null;
    return '🌆 *' + n + ', fim de tarde*' + NL + NL + (b.length ? b.join(NL + NL) + (pergunta ? NL + NL : '') : '') + pergunta;
  }
  if (mom === 'noite') {
    const b = [];
    if (x.gastos.length) {
      const tot = x.gastos.reduce((s, r) => s + (Number(r.valor) || 0), 0);
      b.push('💰 *Gastos de hoje:* ' + brl(tot) + ' em ' + x.gastos.length + (x.gastos.length === 1 ? ' lançamento' : ' lançamentos') + NL + x.gastos.slice(0, 6).map(r => '• ' + (r.descricao || r.categoria || 'gasto') + ' — ' + brl(r.valor)).join(NL) + (x.gastos.length > 6 ? NL + '• +' + (x.gastos.length - 6) + ' outros' : ''));
    } else b.push('💰 Hoje não registrei nenhum gasto seu.');
    if (x.receitas.length) b.push('💵 *Entradas:* ' + brl(x.receitas.reduce((s, r) => s + (Number(r.valor) || 0), 0)));
    const nl = x.feitos.length + x.semOk.length + x.proximos.length;
    if (nl) b.push('⏰ *Lembretes:* ' + x.feitos.length + (x.feitos.length === 1 ? ' feito' : ' feitos') + (x.semOk.length ? ', ' + x.semOk.length + ' sem ok' : '') + (x.proximos.length ? ', ' + x.proximos.length + ' ainda hoje' : ''));
    if (x.feitasHoje.length || x.abertas.length) b.push('📋 *Tarefas:* ' + x.feitasHoje.length + (x.feitasHoje.length === 1 ? ' concluída hoje, ' : ' concluídas hoje, ') + x.abertas.length + (x.abertas.length === 1 ? ' aberta' : ' abertas'));
    return '🌙 *' + n + ', seu dia em resumo*' + NL + NL + b.join(NL + NL) + NL + NL + '*Faltou registrar alguma coisa de hoje?* Me manda que eu anoto agora. Boa noite! 💚';
  }
  if (mom === 'checkin') {
    if (x.ativo2h) return null;
    return agora.hour < 12
      ? '👋 ' + n + ', passando pra lembrar: gastou algo hoje cedo? Café, Uber, padaria... me manda que eu anoto.'
      : '👋 ' + n + ', tudo certo por aí? Não esqueceu de registrar o almoço ou algum gasto da manhã?';
  }
  return null;
}
function textoFamilia(mom) {
  if (mom === 'manha') return null; // a família já recebe o resumo das 06:00 no grupo
  const partes = [];
  for (const a of FAMILIA) {
    const x = dados(a);
    if (mom === 'checkin') { if (!x.ativo2h) partes.push(a); continue; }
    const b = [];
    if (x.proximos.length) b.push(x.proximos.slice(0, 6).map(linhaL).join(NL));
    if (x.semOk.length) b.push('🔔 esperando ok: ' + x.semOk.slice(0, 4).map(r => String(r.texto || '').split(NL)[0].slice(0, 60)).join('; '));
    if (x.contas.length) b.push('💸 vence hoje: ' + x.contas.slice(0, 4).map(r => r.descricao || r.beneficiario || 'conta').join(', '));
    if (mom === 'noite') {
      b.push('💰 ' + (x.gastos.length ? x.gastos.length + (x.gastos.length === 1 ? ' lançamento hoje' : ' lançamentos hoje') : 'nenhum gasto registrado hoje'));
      if (x.feitos.length || x.feitasHoje.length) b.push('✅ feitos hoje: ' + x.feitos.length + (x.feitos.length === 1 ? ' lembrete' : ' lembretes') + ', ' + x.feitasHoje.length + (x.feitasHoje.length === 1 ? ' tarefa' : ' tarefas'));
    }
    if (b.length) partes.push('*' + a + ':*' + NL + b.join(NL));
  }
  if (mom === 'checkin') return partes.length ? '👋 ' + partes.join(', ') + ': gastaram algo hoje? Me manda aqui que eu anoto. — Dyno 🤖' : null;
  if (mom === 'tarde') {
    const quietos = FAMILIA.filter(a => !dados(a).ativo2h);
    if (!partes.length) return quietos.length ? '🌆 ' + quietos.join(', ') + ': teve algum gasto à tarde que ainda não registraram? 😉 — Dyno 🤖' : null;
  }
  if (!partes.length && mom !== 'noite') return null;
  const titulo = { meio_dia: '🕛 *Resumo do meio-dia*', tarde: '🌆 *Fim de tarde*', noite: '🌙 *Resumo do dia*' }[mom];
  const fecho = mom === 'noite' ? 'Faltou registrar alguma coisa de hoje? Me manda aqui que eu anoto. Boa noite! 💚' : mom === 'tarde' ? 'Teve algum gasto à tarde que ainda não registraram? 😉' : '';
  return titulo + (partes.length ? NL + NL + partes.join(NL + NL) : '') + (fecho ? NL + NL + fecho : '');
}
const momentos = M.teste ? ['manha', 'checkin', 'meio_dia', 'tarde', 'noite'] : [M.momento];
const out = [];
for (const mom of momentos) {
  for (const a of Object.keys(dest)) {
    if (FAMILIA.includes(a)) continue;
    const t = textoCliente(a, mom);
    if (t) out.push({ json: { momento: mom, autor: a, numero: dest[a], texto: t } });
  }
  const f = textoFamilia(mom);
  if (f) out.push({ json: { momento: mom, autor: null, numero: GRUPO, texto: f } });
}
return out.map(i => ({ json: { ...i.json, teste: !!M.teste } }));

// Em teste manual nada é enviado: só montamos as mensagens para conferir.
// A assinatura agora vem no cabeçalho (Dina/Dyno), então tiramos o '— Dyno 🤖' antigo.
return $input.all().filter(i => !i.json.teste).map(i => ({ json: { ...i.json, texto: String(i.json.texto || '').replace(/\s*— Dyno 🤖/g, '') } }));
